// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: index < 10 ? 3 : index < 20 ? 4 : 5,
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + ' классы',
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + grade + '.pdf',
      answersUrl: 'assets/medvezhonok/' + year + '/' + grade + '-answers.pdf',
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2012, "2-3", [{"author":"К. Гилярова","question":"По шахматным полям ходит","choices":["пёс","кот","конь","бык","петух."],"key":"В","review":["На шахматных полях","Вопрос про шахматную доску. Вспомни, как называются её фигуры.","Одна из фигур называется конём и похожа на лошадиную голову. Пса, кота, быка и петуха среди фигур нет."]},{"author":"Б. Иомдин","question":"Какого слова не существует?","choices":["<em>прабабушки</em>","<em>правнуки</em>","<em>прадети</em>","<em>прадедушки</em>","все эти слова существуют."],"key":"В","review":["Названия родных","Маму бабушки называют прабабушкой, папу дедушки — прадедушкой. Дети твоих внуков — правнуки.","Приставка пра- показывает связь с более дальними поколениями, но так образуются не все названия. У детей есть свои потомки — внуки и правнуки. Обычного слова «прадети» нет."]},{"author":"И. Рубанов","question":"Смех, грохот, шелест. Какой из этих звуков обычно самый тихий, а какой — самый громкий?","choices":["самый тихий — смех, самый громкий — грохот","самый тихий — шелест, самый громкий — смех","самый тихий — смех, самый громкий — шелест","самый тихий — шелест, самый громкий — грохот","самый тихий — грохот, самый громкий — смех."],"key":"Г","review":["Три звука","Представь шелест листьев, смех и грохот камней, падающих с высоты.","Листья едва слышны, поэтому тише всего шелест. Падающие камни слышно издалека, поэтому громче всего грохот."]},{"author":"И. Рубанов","question":"Последняя согласная буква в алфавите — это","choices":["<em>Я</em>","<em>Ш</em>","<em>Ъ</em>","<em>Щ</em>","<em>Ь</em>."],"key":"Г","review":["Конец алфавита","Прочитай конец алфавита по порядку. За Ш идёт Щ, затем Ъ, Ы, Ь, Э, Ю, Я.","Ъ и Ь звуков не обозначают, а Ы, Э, Ю, Я — гласные. Из согласных дальше всех стоит Щ."]},{"author":"С. Бурлак, Б. Иомдин, С. Переверзева и И. Рубанов","question":"Маленький Федот решил наблюдать за погодой. Утром посмотрел в окно — дождь идёт. Записал в дневник: <em>Идёт дождь</em>. Днём посмотрел — а дождя нет. Записал: <em>Дождь перестал</em>. Вечером ещё раз посмотрел в окно. А там дождь. Что записать Федоту?","choices":["<em>Дождь ещё идёт</em>.","<em>Дождь опять идёт</em>.","<em>Дождь уже идёт</em>.","<em>Дождь всё идёт</em>.","<em>Дождь пока идёт</em>."],"key":"Б","review":["Дневник Федота","Проследи за погодой по записям. Утром шёл дождь, днём он закончился, вечером начался снова.","Слово «опять» показывает, что событие повторилось после перерыва. Федот запишет «Дождь опять идёт»."]},{"author":"О. Подлесская","question":"Какое слово нельзя вставить вместо многоточия во фразу\n<em>У меня есть … друзей</em>?","choices":["<em>пара</em>","<em>трое</em>","<em>пятерня</em>","<em>дюжина</em>","<em>сотня</em>."],"key":"В","review":["Сколько друзей","Посмотри, какие слова отвечают на вопрос «сколько друзей?». Пара — два, трое — три, дюжина — двенадцать, сотня — сто.","«Пятерня» означает кисть руки с пятью пальцами. Для числа друзей подойдёт «пять» или «пятеро», поэтому «пятерня» лишняя."]},{"author":"С. Бурлак","question":"<em><u>Винни-Пух</u></em> <em>и</em> <em><u>поросёнок Пятачок</u></em> <em>— друзья.</em> В этом предложении подчёркнутые части можно поменять местами: <em><u>Поросёнок Пятачок</u></em> <em>и</em> <em><u>Винни-Пух</u></em> <em>— друзья</em>. В каком предложении этого сделать <strong>нельзя</strong>?","choices":["<em><u>Винни-Пух</u></em> <em>и</em> <em><u>Пятачок</u></em> <em>пошли в гости к Иа-Иа</em>.","<em>Винни-Пух</em> <em><u>сочинял кричалку</u></em> <em>и</em> <em><u>ел мёд</u></em>.","<em>Пятачок</em> <em><u>споткнулся</u></em> <em>и</em> <em><u>упал</u></em>.","<em>Ослику подарили</em> <em><u>пустой горшочек</u></em> <em>и</em> <em><u>лопнувший шарик</u></em>.","<em>Иа-Иа было</em> <em><u>смешно</u></em> <em>и</em> <em><u>грустно</u></em>."],"key":"В","review":["Перестановка в предложении","Проверь, можно ли поменять местами соединённые словом «и» части. Имена, подарки и чувства можно перечислить в любом порядке. Есть мёд и сочинять тоже можно одновременно.","Пятачок сперва споткнулся и от этого упал. Если сказать «упал и споткнулся», изменится порядок событий."]},{"author":"Е. Кац","question":"Никто никогда не видел","choices":["<em>стаю уток</em>","<em>стаю акул</em>","<em>стаю волков</em>","<em>стаю коров</em>","<em>стаю ворон</em>."],"key":"Г","review":["Животные вместе","Вспомни, как называют группу летящих уток, ворон или плывущих акул. Это стая, как и группа волков.","Когда вместе пасётся много коров, говорят «стадо коров». Поэтому сочетание «стая коров» не подходит."]},{"author":"Л. Фёдорова","question":"Петя опоздал на урок. Как ему правильно спросить: _______<em>, можно войти?</em>","choices":["<em>Разрешите</em>","<em>Простите</em>","<em>Пустите</em>","<em>Прошу</em>","<em>Проспал</em>."],"key":"Б","review":["Опоздание на урок","В первой части фразы Петя обращается к учителю, а словами «можно войти?» уже спрашивает разрешения.","Поскольку он опоздал, уместно сначала извиниться. Получается «Простите, можно войти?»"]},{"author":"Е. Кац","question":"Студент из Германии, изучающий русский язык, вошёл на кухню и спросил:\n— <em>Есть пить?</em>\n— <em>Пить есть, есть нет</em>, — ответил ему второй студент.\nЧто он хотел сказать?","choices":["В доме есть еда, но нет питья.","В доме нет ни еды, ни питья.","В доме есть питьё, но нет еды.","В доме есть и еда, и питьё.","Мы будем сначала пить, а потом есть."],"key":"В","review":["Разговор на кухне","Замени глаголы «пить» и «есть» на выражения «что попить» и «что поесть».","В ответе выходит «Что попить — есть, что поесть — нет». В доме есть питьё, а еды нет."]},{"author":"К. Гилярова","question":"<em>Сёстры Саша и Глаша родились в один день. Они …</em>","choices":["<em>двойки</em>","<em>двойники</em>","<em>двойнята</em>","<em>двойняшки</em>","<em>двушки</em>."],"key":"Г","unrated":"У этой архивной формулировки есть несколько толкований. Задача доступна без начисления баллов.","review":["Саша и Глаша","В этой задаче сёстры родились у одной мамы в один день. Если два малыша появились от одной беременности, их называют двойней.","Саша и Глаша — двойняшки. Слово «двойнята» с тем же значением встречается в просторечии. Для обычного названия в этой задаче выбираем вариант Г."]},{"author":"Л. Фёдорова","question":"<em>Стрекозе куёт __________</em>\n<em>Крылышки-обновки,</em>\n<em>А для мухи-цокотухи</em> —\n<em>Звонкие подковки.</em>\nКакое слово мы пропустили в этом четверостишии?","choices":["<em>петух</em>","<em>муравей</em>","<em>пчела</em>","<em>паук</em>","<em>кузнечик</em>."],"key":"Д","review":["Звонкие подковки","Прочитай «куёт крылышки» и «звонкие подковки». В настоящей мастерской кует металл кузнец.","«Кузнечик» похож по звучанию на слово «кузнец» и, как стрекоза и муха, является насекомым. В стихах ему досталась роль кузнеца."]},{"author":"Н. Добрушина","question":"<em>Глухой слыхал, как немой сказал, что слепой видал, как хромой …</em>","choices":["<em>играл</em>","<em>читал</em>","<em>болтал</em>","<em>бежал</em>","<em>лежал</em>."],"key":"Г","review":["Небылица","Найди в предложении цепочку невозможных действий. Глухой слышит, немой говорит, слепой видит.","В конце тоже нужно действие, которое хромому трудно выполнить, — «бежал». Так сохраняется шутка."]},{"author":"А. Пиперски","question":"<em>Заливные ..., наливные ..., проливные ...</em>","choices":["<em>яблочки</em>, <em>луга</em>, <em>дожди</em>","<em>луга</em>, <em>яблочки</em>, <em>дожди</em>","<em>дожди</em>, <em>луга</em>, <em>яблочки</em>","<em>дожди</em>, <em>яблочки</em>, <em>луга</em>","<em>яблочки</em>, <em>дожди</em>, <em>луга</em>."],"key":"Б","review":["Три похожих слова","Составь привычные сочетания. Заливные луга заливает водой, а наливные яблочки созрели и полны сока.","Проливной дождь льёт очень сильно. Имена существительные стоят в порядке «луга, яблочки, дожди»."]},{"author":"С. Бурлак","question":"Расставьте предложения в правильном порядке:\n1) <em>Испугался лосёнок и обратно в лес убежал</em>.\n2) <em>Вышел как-то раз лосёнок на опушку</em>.\n3) <em>Это трактор мотор заводил</em>.\n4) <em>А там что-то вдруг как затарахтит!</em>","choices":["4, 3, 2, 1","1, 4, 3, 2","3, 4, 2, 1","2, 1, 3, 4","2, 4, 3, 1."],"key":"Д","review":["Лосёнок на опушке","Найди, где герой появляется на опушке. После этого можно сказать «а там», потому что теперь известно, о каком месте речь.","Сначала раздаётся тарахтение, затем рассказчик объясняет, что трактор заводил мотор. Испуг лосёнка и его побег завершают рассказ. Порядок 2, 4, 3, 1."]},{"author":"Л. Фёдорова","question":"Какое из имён описывает внешность сказочной героини не таким способом, как остальные?","choices":["<em>Белоснежка</em>","<em>Синеглазка</em>","<em>Златовласка</em>","<em>Чернобровка</em>","все четыре имени описывают внешность сказочной героини одним и тем же способом."],"key":"А","review":["Сказочные имена","Разбери имена по частям. У Синеглазки синие глаза, у Златовласки золотые волосы, у Чернобровки чёрные брови.","В этих именах названа часть внешности. Имя Белоснежки сравнивает её со снегом по цвету."]},{"author":"И. Иткин","question":"В русской литературе позапрошлого века иногда встречается выражение <em>ушатая</em> <em>шапка</em>. А сейчас мы обычно называем этот головной убор ...","choices":["<em>ушастая</em> <em>шапка</em>","<em>ушастик</em>","<em>ушанка</em>","<em>ушан</em>","<em>ушат</em>."],"key":"В","review":["Ушатая шапка","Представь шапку с деталями, которые закрывают уши. Именно их раньше называли ушами шапки.","Современное название такой шапки — «ушанка». «Ушат» обозначает деревянную ёмкость с ручками."]},{"author":"Л. Фёдорова","question":"По-шведски <em>мур</em> — ‘мать’, <em>фар</em> — ‘отец’, <em>барн</em> — ‘ребёнок’, <em>барнбарн</em> — ‘внук’ или ‘внучка’. Кто такие <em>мурмур</em> и <em>фарфар</em>?","choices":["матери и отцы","мамочка и папочка","бабушка и дедушка","дочь и сын","тётя и дядя."],"key":"В","review":["Шведская семья","«Барнбарн» можно перевести по частям как «ребёнок ребёнка». Твой внук или внучка и есть ребёнок твоего ребёнка.","Так же разбери «мурмур» и «фарфар». Мать матери — бабушка, отец отца — дедушка."]},{"author":"К. Гилярова и Б. Иомдин","question":"В каком слове не спрятано число?","choices":["<em>внутри</em>","<em>родинка</em>","<em>подвал</em>","<em>стол</em>","<em>путешествие</em>."],"key":"Д","review":["Число внутри слова","Ищи рядом стоящие буквы, из которых складывается название числа. Во «внутри» есть «три», в «родинка» — «один».","В «подвал» есть «два», в «стол» — «сто». В слове «путешествие» ни одно название числа целиком не спряталось."]},{"author":"Т. Заболотская","question":"Какие из подчёркнутых букв слова <em><u>т</u></em><em>е</em><em><u>т</u></em><em>ра</em><em><u>д</u></em><em>ка</em> обозначают звук [т]?","choices":["первая и вторая","первая и третья","вторая и третья","только вторая","все три."],"key":"В","review":["Звуки в слове «тетрадка»","Произнеси обе подчёркнутые буквы т. Перед «е» первая звучит мягко, [т’], а перед «р» вторая звучит твёрдо, [т].","Перед глухим [к] буква д тоже звучит как [т]. Нужный звук дают вторая и третья подчёркнутые буквы."]},{"author":"Е. Бикмаев и К. Кноп","question":"Дима с Таней играли в «Слова» (наподобие игры в «Города», но по более сложным правилам). Вот какой ряд слов у них получился:\n<em>автобус</em> — <em>суббота</em> — <em>атом</em> — <em>моток</em> — ... — <em>колос</em> — <em>соль.</em>\nКакое слово стояло на месте многоточия?","choices":["<em>кошелёк</em>","<em>колобок</em>","<em>котелок</em>","<em>котёнок</em>","из четырёх перечисленных слов ни одно не подходит."],"key":"В","review":["Игра в слова","Переверни три последние буквы слова «автобус». Из «бус» получается «суб» — начало «субботы». Так же «ота» превращается в «ато».","После «моток» нужно начало «кот», потому что слово кончается на «ток». Перед «колосом» нужен конец «лок». Обе части есть в слове «котелок»."]},{"author":"К. Гилярова и М. Сараева","question":"Какой цветок трёхлетняя Таня называет <em>позвоночник</em>?","choices":["подснежник","подсолнечник","одуванчик","колокольчик","василёк."],"key":"Г","review":["Танино название цветка","Напиши гласные буквы слова «позвоночник» по порядку — о, о, о, и. Послушай, на какую из них падает ударение. Оно падает на третью, «позвоно́чник».","У цветка «колоко́льчик» те же четыре гласные и ударение тоже на третьей. Среди вариантов только это название подходит по обоим признакам."]},{"author":"К. Гилярова","question":"Закончите скороговорку: <em>Сшит колпак, да не по-колпаковски, вылит</em> <em>колокол, да не по-колоколовски. Надо колпак переколпаковать,</em> <em>перевыколпаковать, надо колокол</em> …","choices":["<em>перековать</em>, <em>перевыковать</em>","<em>переколовать</em>, <em>перевыколовать</em>","<em>переколоковать</em>, <em>перевыколоковать</em>","<em>переколоколать</em>, <em>перевыколоколать</em>","<em>переколоколовать</em>, <em>перевыколоколовать</em>."],"key":"Д","review":["Скороговорка про колокол","Посмотри, что сделали со словом «колпак». Перед ним появились «пере-» и «перевы-», а в конце добавилось «-овать».","Приставь те же части к целому слову «колокол». Получится «переколоколовать, перевыколоколовать»."]},{"author":"И. Иткин","question":"<em>Здесь ... и груши</em>\n<em>Бегут по сторонам</em>\n<em>И яблоки и ...</em>\n<em>Протягивают нам.</em>\nКак правильно заполнить пропуски в этом четверостишии из стихотворения Льва Друскина?","choices":["<em>яблоки</em>, <em>груши</em>","<em>яблони</em>, <em>груши</em>","<em>яблоки</em>, <em>вишни</em>","<em>яблони</em>, <em>вишни</em>","<em>ясени</em>, <em>груши</em>."],"key":"Б","review":["Деревья у дороги","Представь дорогу, вдоль которой растут плодовые деревья. Яблоки растут на яблонях, а «груши» могут означать и деревья, и плоды.","В первых строках по сторонам дороги стоят яблони и груши. В последних деревья протягивают плоды — яблоки и груши."]},{"author":"Л. Фёдорова","question":"В какой паре слов <strong>нет</strong> общих звуков?","choices":["<em>рот</em> — <em>род</em>","<em>нос</em> — <em>нёс</em>","<em>нос</em> — <em>сон</em>","<em>мяч</em> — <em>матч</em>","<em>лес</em> — <em>лось</em>."],"key":"Д","review":["Общие звуки","«Рот» и «род» звучат одинаково. В паре «нос — нёс» общий [с], в «нос — сон» звуки переставлены, а у «мяч» и «матч» есть общие [а] и [ч’].","В «лес» слышатся [л’], [э], [с], а в «лось» — [л], [о], [с’]. Твёрдые и мягкие согласные различаются, поэтому общих звуков нет."]},{"author":"Е. Муравенко","question":"Даны слова родственного русскому сербского языка с переводом на русский («jу» читается в сербском, как русское «ю»): чита — <em>читает</em>, читаjу — <em>читают</em>, знам — <em>знаю</em>, знаjу — <em>знают</em>, игра — <em>играет</em>, играмо — <em>играем</em>. Как будет по-сербски <em>читаем</em>, <em>знает</em>, <em>играю</em>?","choices":["читамо, зна, играм","читам, зна, играjу","читамо, зна, играjу","читамо, знат, играм","читам, знат, игра."],"key":"А","review":["Сербские глаголы","Сопоставь «игра — играет» и «играмо — играем». Для «мы» нужна часть «-мо», поэтому «читаем» будет «читамо».","Для «он» в словах «чита» и «игра» ничего не добавлено, отсюда «зна». В «знам — знаю» для «я» добавили «-м», значит, «играю» — «играм»."]},{"author":"К. Гилярова","question":"Когда у свиньи рождаются поросята, говорят, что она <em>опоросилась</em>. А про корову — что она <em>отелилась</em>. А как правильно сказать про только что родившую лошадь?","choices":["<em>олошадилась</em>","<em>оконилась</em>","<em>ожеребятилась</em>","<em>ожеребёнилась</em>","<em>ожеребилась</em>."],"key":"Д","review":["У лошади появился малыш","«Опоросилась» связано с поросёнком, а «отелилась» — с телёнком. Найди название детёныша лошади.","Детёныша зовут жеребёнком. В глаголе берём часть «жереб-» и получаем «ожеребилась»."]},{"author":"И. Иткин","question":"<em>Ы</em>, <em>Й</em>, <em>Ё</em>, <em>Щ</em>, ... . Какой буквой можно продолжить этот список?","choices":["<em>Ч</em>","<em>Ъ</em>","<em>Ь</em>","<em>Э</em>","<em>Я</em>."],"key":"Б","review":["Детали букв","Посмотри, какие знакомые буквы получится увидеть, если убрать из Ы правую черту, из Й — дугу, из Ё — точки, из Щ — хвостик. Останутся Ь, И, Е и Ш.","У Ъ можно убрать выступ вверху слева и получить Ь. Среди предложенных букв только Ъ превращается в другую букву после удаления детали."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
